// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
    Node(int data) { this.data = data; }
}

public void inorder(Node root) {
    if (root == null) return;          // base case: nothing to visit
    inorder(root.left);                // 1) left subtree first
    System.out.print(root.data + " "); // 2) visit the node
    inorder(root.right);               // 3) right subtree last
}

public void inorder(Node root) {
    Deque<Node> stack = new ArrayDeque<>();
    Node cur = root;
    while (cur != null || !stack.isEmpty()) {
        while (cur != null) {          // push the entire left spine
            stack.push(cur);
            cur = cur.left;
        }
        cur = stack.pop();             // left subtree done → visit
        System.out.print(cur.data + " ");
        cur = cur.right;               // pivot to the right subtree
    }
}

